{
  "name": "VISA消息式实验仪器",
  "name_en": "VISA Message-Based Laboratory Instrument",
  "manufacturer": "",
  "description": "可通过USB、USB RAW、串口、TCP/IP或GPIB进行文本命令通信的通用实验室仪器，如电子测量仪表、源表、电源或分析仪。此类设备通常在实验室中用于远程控制、参数配置、状态读取和测量数据采集。",
  "description_en": "A generic laboratory instrument that communicates through text-based commands over USB, USB RAW, serial, TCP/IP, or GPIB, such as electronic test instruments, source meters, power supplies, or analyzers. These devices are commonly used in laboratories for remote control, parameter configuration, status readback, and measurement data acquisition.",
  "actions": [
    {
      "action_name": "auto-finalize",
      "description": "关闭与仪器的通信会话。",
      "description_en": "Close the communication session with the instrument."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化与仪器的通信会话。",
      "description_en": "Initialize the communication session with the instrument."
    },
    {
      "action_name": "auto-parse_query",
      "description": "向仪器发送查询命令并按指定格式解析返回结果。",
      "description_en": "Send a query command to the instrument and parse the returned result using a specified format."
    },
    {
      "action_name": "auto-query",
      "description": "向仪器发送查询命令并读取返回结果。",
      "description_en": "Send a query command to the instrument and read back the response."
    },
    {
      "action_name": "auto-read",
      "description": "从仪器读取返回的文本数据。",
      "description_en": "Read returned text data from the instrument."
    },
    {
      "action_name": "auto-write",
      "description": "向仪器发送文本命令。",
      "description_en": "Send a text command to the instrument."
    },
    {
      "action_name": "auto-via_usb",
      "description": "通过USB仪器接口连接设备。",
      "description_en": "Connect to the device through a USB instrument interface."
    },
    {
      "action_name": "auto-via_usb_raw",
      "description": "通过USB RAW接口连接设备。",
      "description_en": "Connect to the device through a USB RAW interface."
    },
    {
      "action_name": "auto-via_serial",
      "description": "通过串口连接设备。",
      "description_en": "Connect to the device through a serial port."
    },
    {
      "action_name": "auto-via_tcpip",
      "description": "通过TCP/IP仪器接口连接设备。",
      "description_en": "Connect to the device through a TCP/IP instrument interface."
    },
    {
      "action_name": "auto-via_tcpip_socket",
      "description": "通过TCP/IP套接字接口连接设备。",
      "description_en": "Connect to the device through a TCP/IP socket interface."
    },
    {
      "action_name": "auto-via_gpib",
      "description": "通过GPIB接口连接设备。",
      "description_en": "Connect to the device through a GPIB interface."
    }
  ],
  "tag_hints": [
    "VISA communication",
    "message-based instrument",
    "SCPI control",
    "GPIB",
    "USBTMC",
    "serial instrument control",
    "TCP/IP instrument"
  ]
}

